import{_ as i,o as t,c as o,ai as d}from"./chunks/framework.DAbPic9L.js";const n=JSON.parse('{"title":"产品流程","description":"","frontmatter":{},"headers":[],"relativePath":"disciplines/business/workflow/index.md","filePath":"disciplines/business/workflow/index.md","lastUpdated":1788773686000}'),e={name:"disciplines/business/workflow/index.md"};function c(a,l,r,p,s,b){return t(),o("div",null,[...l[0]||(l[0]=[d('<h1 id="产品流程" tabindex="-1">产品流程 <a class="header-anchor" href="#产品流程" aria-label="Permalink to &quot;产品流程&quot;">​</a></h1><p>文/晨风不可依米</p><br><h2 id="需求分析" tabindex="-1">需求分析 <a class="header-anchor" href="#需求分析" aria-label="Permalink to &quot;需求分析&quot;">​</a></h2><p>核心目的: 搞清楚「做什么、给谁用、解决什么问题」，把模糊诉求变成清晰、可评估的需求。</p><h3 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">业务概念</p><table tabindex="0"><thead><tr><th>名词</th><th>本质</th><th>理解</th></tr></thead><tbody><tr><td>业务概念</td><td>业务对象实体</td><td>采用统一业务语言描述业务对象；如客户、优惠券等。</td></tr><tr><td>业务属性</td><td>业务对象特征</td><td>业务对象的特征内容；如用户名、年龄、性别等。</td></tr><tr><td>业务行为</td><td>业务对象命令、事件</td><td>业务对象的动作行为；如(优惠券)发放、核销、作废等。</td></tr><tr><td>业务规则</td><td>约束业务行为的条件</td><td>业务对象的行为规范；如订单最多只能使用一张优惠券。</td></tr></tbody></table></div><br><div class="tip custom-block"><p class="custom-block-title">需求概念</p><table tabindex="0"><thead><tr><th>名词</th><th>本质</th><th>理解</th></tr></thead><tbody><tr><td>主线任务</td><td>用户活动中切身想要完成的事物； <br> 关注<code>业务目标</code>，即<code>完成事物目标</code>。</td><td>实用消耗、精神消耗</td></tr><tr><td>任务痛点</td><td>围绕在主线任务过程中所遭遇的难题； <br> 关注<code>现状问题</code>，即<code>实施遭遇障碍</code>。</td><td>问题、障碍、关卡点</td></tr><tr><td>用户需求</td><td>围绕在主线任务完成后所产生的价值； <br> 关注<code>价值目标</code>，即<code>解决产生价值</code>。</td><td>诉求、期待、满足感</td></tr><tr><td>功能列表</td><td>用于实现用户需求的具体手段； <br> 关注<code>现状问题</code>，即<code>提供稳定能力</code>。</td><td>具体功能抽象业务能力； <br> 具体功能: <code>增删改查验证</code>。 <br> 业务能力: <code>XX 管理能力</code>。</td></tr></tbody></table></div><br><h3 id="任务痛点" tabindex="-1">任务痛点 <a class="header-anchor" href="#任务痛点" aria-label="Permalink to &quot;任务痛点&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">痛点类型</p><ul><li><p>效率痛点: 重复操作、流程复杂、结果反馈久。</p></li><li><p>成本痛点: 资金成本、人力成本、学习成本等。</p></li><li><p>风险痛点: 操作出错、数据丢失、合规问题等。</p></li><li><p>业务痛点: 利润营收、流程阻塞、管控问题等。</p></li><li><p>体验痛点: 用户习惯、操作入口、信息提示等。</p></li></ul><br><p><strong>深挖痛点</strong></p><p>识别总纲: <code>某个角色</code>在<code>某个场景</code>下完成<code>某个任务</code>，因为<code>某个原因</code>导致<code>某种负面后果</code>。</p></div><br><h3 id="用户需求" tabindex="-1">用户需求 <a class="header-anchor" href="#用户需求" aria-label="Permalink to &quot;用户需求&quot;">​</a></h3><div class="danger custom-block"><p class="custom-block-title">区分概念</p><p>用户需求，关注状态变化的调整。功能列表，关注具体实现的抽象能力。</p><p>由于<code>需求 ≠ 功能</code>，禁止使用<code>系统(我)要 XXX 功能/能力</code>的范式。</p><br><p><strong>归纳需求</strong></p><p>识别总纲: 减少<code>某种现象(成本、风险等方面内容)</code>、提升<code>某种现象(效率、体验等方面内容)</code>。</p></div><br><h3 id="功能列表" tabindex="-1">功能列表 <a class="header-anchor" href="#功能列表" aria-label="Permalink to &quot;功能列表&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">重点理解</p><p>关注具体实现的抽象能力。</p><br><p><strong>总结功能</strong></p><p>识别总纲: 为了实现<code>某种用户需求，系统需要 XX 能力</code>；即<code>具体功能抽象为业务能力</code>。</p></div><br><h2 id="领域设计" tabindex="-1">领域设计 <a class="header-anchor" href="#领域设计" aria-label="Permalink to &quot;领域设计&quot;">​</a></h2><p>核心目的: 剥离技术实现，纯粹梳理业务本身的逻辑、实体、关系，建立统一业务语言。</p><h3 id="核心概念-1" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念-1" aria-label="Permalink to &quot;核心概念&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">领域概念</p><table tabindex="0"><thead><tr><th>概念</th><th>归属</th><th>本质</th><th>理解</th></tr></thead><tbody><tr><td>领域</td><td>战略设计</td><td>问题范围</td><td>业务问题的总和</td></tr><tr><td>子域</td><td>战略设计</td><td>业务问题</td><td>问题范围的细分</td></tr><tr><td>限界上下文</td><td>战略设计</td><td>业务边界</td><td>业务语义边界，建立统一语言，消除歧义。 <br> 上下文协作，注意调用时产生其它域业务逻辑。</td></tr><tr><td></td><td></td><td></td><td></td></tr><tr><td>模块</td><td>战术设计</td><td>组织、包块</td><td>限界上下文按职责划分的命名空间</td></tr><tr><td>聚合</td><td>战术设计</td><td>事务一致性</td><td>业务术语仅限当前识别</td></tr><tr><td>服务</td><td>战术设计</td><td>业务行为</td><td>非实体、值对象等无状态对象的业务逻辑封装</td></tr><tr><td></td><td></td><td></td><td></td></tr><tr><td>能力</td><td>业务架构</td><td>潜能</td><td>将功能抽象为能力(<code>xx管理能力</code>)</td></tr><tr><td>功能</td><td>需求工程</td><td>特性</td><td>系统对外提供的具体可操作特性(<code>增删改查验证</code>)</td></tr></tbody></table><br><p><strong>深化理解</strong></p><ol><li><p>领域 VS 子域 VS 限界上下文</p><p>领域: 强调范围；如森林范围，即森林领域。</p><p>子域: 强调细分；如森林中的灌木区、果树区、水源区，即森林子域。</p><p>限界上下文: 强调边界；如森林中的果树区(<code>由于协作关系，可能包含水源区部分业务逻辑-水渠引水</code>)，即森林果树区限界上下文。</p></li></ol><br><ol start="2"><li><p>模块 VS 聚合</p><p>模块: 关注代码组织，特点为高内聚、低耦合；如目录结构，代码包。</p><p>聚合: 关注建模聚合，特点为保证事务一致性；如建模聚合业务对象。</p></li></ol><br><ol start="3"><li><p>服务 VS 能力 VS 功能</p><p>服务: 技术(<code>设计视角</code>)角度上非实体、值对象等无状态对象的业务逻辑封装。</p><p>能力: 业务(<code>战略设计</code>)角度上系统的处理能力。</p><p>功能: 用户(<code>产品视角</code>)角度上模块的具体功能。</p></li></ol><br><p><strong>系统设计</strong></p><ol><li>业务架构层</li></ol><ul><li>领域层 <ul><li><p>核心子域</p></li><li><p>支撑子域</p></li><li><p>通用子域</p></li><li><p>具体子域(<code>详解</code>)</p><ul><li>能力地图 <ul><li>xx 管理能力</li><li>yy 处理能力</li><li>zz 管控能力</li></ul></li></ul></li></ul></li></ul><br><ol start="2"><li>战略设计层</li></ol><ul><li>限界上下文 <ul><li>xx 上下文: 对应 xx 管理能力</li><li>yy 上下文: 对应 yy 处理能力</li><li>zz 上下文: 对应 zz 管控能力</li></ul></li></ul><br><ol start="3"><li>战术设计层</li></ol><ul><li>模块包 <ul><li>领域包 <ul><li>聚合包</li><li>实体包</li><li>值对象包</li><li>领域服务包</li><li>领域事件包</li><li>领域仓储包(<code>依赖解耦: 抽象接口</code>)</li></ul></li><li>基建包 <ul><li>加密包</li><li>缓存包</li><li>数据库包</li></ul></li><li>应用包 <ul><li>查询包</li><li>命令包</li></ul></li><li>接口包 <ul><li>HTTP 协议包</li><li>gRPC 协议包</li><li>SSE 协议包</li><li>WS 协议包</li><li>具体协议包(<code>详解</code>) <ul><li>协议规范(<code>DTO</code>、<code>PROTO</code>)</li><li>功能接口 <ul><li>查询 xx 列表</li><li>查询 xx 详情</li><li>其它 xx 接口</li></ul></li></ul></li></ul></li></ul></li></ul><br><ol start="4"><li>用户需求层</li></ol><ul><li>功能列表 <ul><li>xx 创建: 由 xx 服务编排，初始化配置。</li><li>xx 更新: 由 xx 聚合更新状态。</li><li>xx 删除: 由 xx 聚合更新状态。</li><li>xx 查询: 查询 xx 聚合对象。</li><li>xx 验证: 检测 xx 聚合对象存在性。</li></ul></li></ul></div><br><h3 id="建模流程" tabindex="-1">建模流程 <a class="header-anchor" href="#建模流程" aria-label="Permalink to &quot;建模流程&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">建模流程</p><ol><li>业务流程(<code>行业真实业务知识</code>)</li><li>事件提取(<code>识别业务发生的事实</code>)</li><li>命令推导(<code>识别业务变更的动作</code>)</li><li>聚合关联(<code>梳理业务对象间的候选聚合线索</code>)</li><li>业务簇成块(<code>将高内聚元素收拢为粗粒度业务能力簇</code>)</li><li>子域划分(<code>价值分层: 核心、支撑、通用等领域</code>)</li><li>限界上下文(<code>划定独立的业务语义边界，确立统一语言</code>)</li><li>上下文映射(<code>定义各个限界上下文之间的协作与依赖关系</code>)</li><li>战略评审(<code>对整套战略划分方案进行评估校验</code>)</li><li>聚合(<code>定义业务事务与强一致性边界</code>)</li><li>实体(<code>具备唯一标识、状态可变的业务对象</code>)</li><li>值对象(<code>无唯一标识、整体不可变，自带校验规则的描述对象</code>)</li><li>领域服务(<code>非实体、值对象的跨聚合业务逻辑封装</code>)</li><li>领域仓储(<code>聚合持久化抽象接口，解耦数据库实现</code>)</li><li>领域事件(<code>聚合完成变更后发布，实现跨边界解耦协作</code>)</li><li>战术评审(<code>校验上下文内部领域模型的合理性</code>)</li></ol></div><br><h3 id="建模工具" tabindex="-1">建模工具 <a class="header-anchor" href="#建模工具" aria-label="Permalink to &quot;建模工具&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">事件风暴</p><p>基于头脑风暴形式，通过业务专家、开发人员、产品经理等不同角色共同参与，聚焦于具体的问题领域，由事件推导命令、关联构建业务簇，并经过战略设计、战术设计等要求，消除技术与业务的隔阂。</p><p>事件命令反映了系统如何解决问题，建模聚合反映了数据状态和系统运作细节。</p><p>事件风暴是一种高度迭代的过程，全局视角理解业务流程。通过团队研讨和事件梳理，可发现业务流程隐性问题，以便团队快速调整和完善模型，适应业务需求的变化。</p><br><p><strong>事件风暴概念</strong></p><table tabindex="0"><thead><tr><th>概念</th><th>本质</th></tr></thead><tbody><tr><td>业务流程</td><td>业务逻辑有序编排执行命令，业务解耦，事件通知。</td></tr><tr><td>领域事件</td><td>业务流程中已发生的事实，由<code>名词 + 动词过去式</code>构成。</td></tr><tr><td>用户</td><td>通过视图执行命令的人。</td></tr><tr><td>命令</td><td>用户通过聚合视图执行的命令，导致创建域事件。</td></tr><tr><td>聚合</td><td>一组关联多个实体对象的集合。</td></tr><tr><td>外部系统</td><td>第三方服务提供商(<code>第三方聚合对象</code>)。</td></tr><tr><td>视图模型</td><td>用户与系统交互以执行任务的视图(<code>查询</code>)。</td></tr></tbody></table><br><p><strong>事件风暴流程</strong></p><p>通过业务专家、开发人员、产品经理等不同角色共同参与，梳理领域事件、命令、参与者、策略。</p><ol><li>编排领域事件 <ul><li>按时间顺序，收集并记录领域事件。</li><li>领域事件按照<code>名词 + 动词过去式</code>命名。</li></ul></li></ol><br><ol start="2"><li>细化领域事件 <ul><li>建立统一业务语言(<code>命名、语义</code>)。</li><li>同一对象在不同场景的叫法不同。</li></ul></li></ol><br><ol start="3"><li>事件触发原因(<code>过程建模</code>) <ul><li>用户操作(<code>用户、命令、查询</code>)要素。</li><li>外部系统(<code>第三方聚合对象</code>)要素。</li><li>时间要素(<code>定时触发、业务流程</code>)要素。</li><li>其它领域事件要素。</li><li>从四要素询问事件触发原因，在有序领域事件中可识别缺失事件，并提出解决方案。</li><li>另外，完整有序的领域事件链路，可强化对业务流程的理解。</li></ul></li></ol><br><ol start="4"><li>重排领域事件(<code>软件建模</code>) <ul><li>哪些用户触发哪些命令。</li><li>哪些命令会影响哪些聚合或外部系统，并触发哪些更改。</li><li>在命令处理过程中，哪些聚合或外部系统触发了哪些事件。</li><li>哪些事件触发了哪些策略。</li><li>哪些事件为哪些用例创建了哪些阅读模型。</li><li>哪些策略会调用哪些新命令。</li><li>以上要素的考量，可识别添加领域事件到聚合对象，并应用到界限上下文中。</li></ul></li></ol></div><br><div class="tip custom-block"><p class="custom-block-title">聚类分组</p><p>将业务流程中存在强关联、高内聚、同时变更的元素对象，打包成业务簇(<code>暂时不存在业务边界</code>)。</p><p>通过<code>事件风暴</code>之后，我们可得<code>事件</code>、<code>命令</code>、<code>用户</code>、<code>聚合</code>、<code>外部系统</code>、<code>视图模型</code>等聚类要素内容。</p><br><p><strong>聚类标准</strong></p><ul><li>同属一套业务术语，业务规则。</li><li>业务流程变化，同时变更事件、命令。</li><li>业务功能同属于一个完整的业务能力。</li></ul><br><p><strong>案例详解</strong></p><ol><li>事件风暴产出的聚类要素 <ul><li>创建用户</li><li>修改用户</li><li>冻结用户</li><li>解冻用户</li><li>注销用户</li><li>用户已冻结</li><li>用户已注销</li><li>用户已解冻</li><li>创建订单</li><li>修改地址</li><li>提交支付</li><li>订单已创建</li><li>订单已支付</li><li>订单已超时</li></ul></li></ol><br><ol start="2"><li>高内聚元素收拢为业务能力 <ul><li><p>用户管理能力</p><ul><li>创建用户</li><li>修改用户</li><li>冻结用户</li><li>解冻用户</li><li>注销用户</li><li>用户已冻结</li><li>用户已注销</li><li>用户已解冻 <br><br></li></ul></li><li><p>订单履约能力</p><ul><li>创建订单</li><li>修改地址</li><li>提交支付</li><li>订单已创建</li><li>订单已支付</li><li>订单已超时</li></ul></li></ul></li></ol><br><p><strong>特别注意</strong></p><ul><li>业务簇(<code>临时分组</code>) ≠ 限界上下文(<code>最终确定</code>)。</li><li>业务簇 = 临时的业务分组草稿（<code>临时分组的业务能力</code>）。</li><li>限界上下文 = 战略评审后最终确定的业务语义边界，并构建统一业务语言。</li></ul></div><br><h3 id="战略设计" tabindex="-1">战略设计 <a class="header-anchor" href="#战略设计" aria-label="Permalink to &quot;战略设计&quot;">​</a></h3><p>核心内容: 解决组织与业务拆分问题；关注<code>业务问题</code>、<code>业务范围</code>、<code>系统拆分</code>、<code>团队分工</code>。</p><br><div class="warning custom-block"><p class="custom-block-title">识别子域</p><p>对每一个业务簇进行价值分层；基于业务簇和子域判断，确定最终业务边界。</p><br><p><strong>价值分层</strong></p><ul><li><p>核心域: 企业核心竞争力，产品业务的重点。</p></li><li><p>支撑域: 保证业务运行通畅，不作差异化价值；。</p></li><li><p>通用域: 全系统服用的基础能力；如用户、身份、权限。</p></li></ul><br><p><strong>分层考量</strong></p><ul><li><p>内聚: 哪些业务簇可合并为一个上下文。</p></li><li><p>解耦: 哪些业务簇必须拆分独立上下文。</p></li></ul><br><p><strong>统一语言</strong></p><ul><li><p>在同一个上下文内，统一采用同一套业务语言。</p></li><li><p>跨业务边界，允许同名但不同含义的内容。</p></li><li><p>限界上下文，消除技术与业务的隔阂；同时确定未来微服务、模块包的结构边界。</p></li></ul></div><br><div class="warning custom-block"><p class="custom-block-title">上下文映射</p><p>关注上下文间的依赖与协作，不关注上下文对象内部实现细节。</p><ul><li><p>上下文映射图: A 上下文依赖 B 上下文 XX 能力。</p></li><li><p>上下文协作模式: 发布-订阅事件、防腐层 ACL 隔离。</p></li></ul></div><br><h3 id="战术设计" tabindex="-1">战术设计 <a class="header-anchor" href="#战术设计" aria-label="Permalink to &quot;战术设计&quot;">​</a></h3><p>核心内容: 解决代码建模实现业务逻辑；关注<code>业务对象</code>、<code>业务规则</code>、<code>业务建模</code>、<code>领域模型</code>。</p><br><div class="warning custom-block"><p class="custom-block-title">识别聚合边界</p><p>基于聚合保证事务一致性边界，并细化拆分实体、值对象、领域服务、领域事件，完成可指导开发的领域模型。</p><ol><li>根据<code>业务有无身份唯一标识</code>划分实体和值对象。</li><li>通过<code>非实体、值对象的跨聚合业务逻辑</code>确定领域服务。</li><li>通过<code>上下文依赖与协作的协议接口</code>触发领域事件。</li><li>基于<code>实体</code>以及<code>事务一致性边界</code>划分候选聚合。</li><li>领域仓库的本质: 数据库实现的<code>抽象接口</code>。</li></ol></div><br><div class="tip custom-block"><p class="custom-block-title">实体</p><p>具备唯一标识，状态可变的业务对象。</p><p>状态可变，并提供改变状态的方法。</p></div><br><div class="warning custom-block"><p class="custom-block-title">值对象</p><p>无唯一标识，整体不可变，自带规则校验的描述对象。</p><p>通过自身业务规则保证数据合法(<code>本质: 值合法</code>)。</p></div><br><div class="tip custom-block"><p class="custom-block-title">聚合</p><p>定义业务事务与强一致性边界，并提供唯一对外访问的接口对象。</p><p>关联一组多个实体，确保事务边界一致性。</p></div><br><div class="warning custom-block"><p class="custom-block-title">领域仓储</p><p>定义聚合存取的抽象，隔离持久化技术细节。</p></div><br><div class="tip custom-block"><p class="custom-block-title">领域服务</p><p>专门存放跨聚合、不属于单个实体的值对象的业务规则。</p></div><br><div class="warning custom-block"><p class="custom-block-title">领域事件</p><p>聚合完成业务变更后向外发布，用于跨上下文解耦协作。</p></div><br><h2 id="架构设计" tabindex="-1">架构设计 <a class="header-anchor" href="#架构设计" aria-label="Permalink to &quot;架构设计&quot;">​</a></h2><p>核心目的: 基于战略设计的界限上下文依赖关系，搭建一套稳定可靠的技术骨架；可简述为<code>概要技术架构</code>。</p><br><h3 id="核心关注" tabindex="-1">核心关注 <a class="header-anchor" href="#核心关注" aria-label="Permalink to &quot;核心关注&quot;">​</a></h3><ul><li>系统风格: 单体架构、微服务架构、事件驱动架构(<code>CQRS、事件溯源</code>)。</li><li>服务映射: 将限界上下文映射为独立服务或模块(<code>康威定律</code>).</li><li>技术选型: 数据库、缓存器、消息队列、配置中心、注册中心、网关服务、中间件。</li><li>通信方案: 同步<code>RPC、REST</code>，异步<code>消息队列</code>。</li><li>基建部署: 容器、集群、扩容、灾备。</li><li>非功能方案: 限流熔断、分布式事务、分库分表、日志监控、权限安全。</li><li>架构验证: 耦合度、高可用、安全性、扩展性。</li></ul><br><h3 id="系统风格" tabindex="-1">系统风格 <a class="header-anchor" href="#系统风格" aria-label="Permalink to &quot;系统风格&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">单体架构</p><p>整个业务系统作为一个应用整体开发、整体部署、整体运行。</p><p>符合敏捷开发快速验证业务流程，源于它在开发、部署、测试、调用、事务上都很简单。</p><p>当系统的服务、依赖越多，所需要的团队协作、部署也越复杂，最终会造成高度耦合。</p><p>系统表现强调<code>业务内聚</code>: 可理解为<code>模块化能力</code>。</p><br><p><strong>微服务架构</strong></p><p>一个大型系统拆成多个可以独立运行、独立部署的业务服务。</p><p>不同业务能力需要不同的生命周期、扩展方式、技术栈、团队职责和部署节奏。</p><p>划分独立微服务，并不是越细越好；建议通过领域驱动设计划分业务边界，确定限界上下文。</p><p>系统表现强调<code>业务解耦</code>: 可理解为<code>独立性服务</code>。</p><br><p><strong>事件驱动架构</strong></p><p>一个业务事实发生之后，其它参与者如何感知并做出反应。它可存在单体架构，也可存在微服务架构。</p><p>系统表现强调<code>业务事实已发生，通知其它参与者</code>；可理解为<code>参与者解耦</code>。</p></div><br><h3 id="服务映射" tabindex="-1">服务映射 <a class="header-anchor" href="#服务映射" aria-label="Permalink to &quot;服务映射&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">康威定律</p><p>通过业务边界(<code>限界上下文</code>)<code>明确业务责任边界与协作边界</code>，再根据这些边界<code>划分团队职责</code>，使负责某个业务边界的<code>团队能够独立负责、协作和演进</code>该边界，从而使软件系统结构尽可能反映组织的沟通与协作结构。</p><br><p>可理解为: <code>基于业务边界划分责任范围与协作关系，并由对应团队独立负责限界上下文的开发、维护与演进；通过双方约定的协作契约，保证业务上相互协作，技术上边界独立</code>。</p><br><p><strong>案例解析</strong></p><ul><li>订单管理系统 <ul><li>租户上下文: 租户</li><li>用户上下文: 用户、实名</li><li>认证上下文: 注册、登录、认证、会话、令牌</li><li>订单上下文: 创建、核销、撤销</li></ul></li></ul><p>以上限界上下文分别由对应团队负责(<code>业务边界、各司其职</code>)，并在上下文之间定义清晰的协作关系。</p></div><br><h3 id="技术选型" tabindex="-1">技术选型 <a class="header-anchor" href="#技术选型" aria-label="Permalink to &quot;技术选型&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">前端技术栈</p><ul><li><p>核心方案: HTML5、CSS3、ES6、TS 等支持。</p></li><li><p>框架方案: Vue3、React20 等支持。</p></li><li><p>大屏方案</p><ul><li>屏幕尺寸检测切换站点，用于布局结构大变化场景。</li><li>媒体查询对应样式文件，用语布局结构小变化场景。</li><li>核心原理 <ul><li>rem: 依赖插件(<code>postcss-pxtorem</code>)，配合监听<code>resize</code>事件改变文档<code>fontsize</code>。</li><li>viewport: 依赖插件(<code>postcss-px-to-viewport</code>)，自动根据屏幕尺寸适配。</li></ul></li></ul><p>弹性、网格等布局方式、监听屏幕尺寸变化进行像素单位(<code>rem: 依赖插件 postcss-pxtorem</code>)转换适配。</p></li></ul><br><p><strong>后端技术栈</strong></p><ul><li><p>核心方案: NodeJS、Java、Go 等支持。</p></li><li><p>框架方案: NestJS、Spring Boot、Gin 等支持。</p></li><li><p>数据缓存方案: Redis 等支持。</p></li><li><p>数据入库方案: Postgres、MySQL、MongoDB 等支持。</p></li><li><p>库表驱动方案: Prisma、TypeORM、Mongoose 等支持。</p></li></ul><br><p><strong>项目托管</strong></p><ul><li><p>版本管理: Git(<code>推荐</code>)、SVN 等支持。</p></li><li><p>托管平台: Gitlab(<code>私有</code>)、Github 等支持。</p></li></ul></div><br><h3 id="通信方案" tabindex="-1">通信方案 <a class="header-anchor" href="#通信方案" aria-label="Permalink to &quot;通信方案&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">接口协议</p><ul><li><p>REST 风格:</p></li><li><p>PROTO 风格:</p></li></ul><br><p><strong>场景应用</strong></p><ul><li><p>同步方案: RPC、REST、HTTP。</p></li><li><p>异步方案: 事件消息队列。</p></li></ul></div><br><h3 id="基建部署" tabindex="-1">基建部署 <a class="header-anchor" href="#基建部署" aria-label="Permalink to &quot;基建部署&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">基础设施</p><ol><li>服务通信 <ul><li>网关服务: 统一入口。</li><li>通信方式: HTTP、REST、RPC。</li><li>负载分配: 降低服务压力。</li><li>服务寻址: DNS。</li><li>通信加密: TLS.</li></ul></li></ol><br><ol start="2"><li>服务治理 <ul><li>服务注册</li><li>服务发现</li><li>健康检查</li><li>负载均衡</li><li>流量控制</li><li>服务降级</li><li>熔断</li><li>限流</li><li>重试</li><li>超时</li></ul></li></ol><br><ol start="3"><li>配置与注册 <ul><li>服务配置</li><li>公共信息</li></ul></li></ol><br><ol start="4"><li>消息与事件 <ul><li>消息代理</li><li>消息队列</li><li>事件总线</li><li>事件流</li><li>死信队列</li><li>重试队列</li></ul></li></ol><br><ol start="5"><li>数据与存储 <ul><li>数据缓存: 读写锁、备份、恢复、迁移、连接池。</li><li>数据入库(<code>独立部署</code>): 读写锁、备份、恢复、迁移、连接池。</li><li>对象存储: 享元不可变。</li><li>数据仓库</li><li>搜索引擎</li><li>分布式数据库</li></ul></li></ol><br><ol start="6"><li>可观测性 <ul><li>日志采集</li><li>日志聚合</li><li>日志检索</li></ul></li></ol><br><ol start="7"><li>安全与身份 <ul><li>身份</li><li>凭证</li><li>认证</li><li>授权</li><li>会话</li><li>密钥</li><li>证书</li><li>加密</li></ul></li></ol><br><ol start="8"><li>部署与运行 <ul><li>容器: Container</li><li>镜像: Kubernetes</li><li>集成交付: CI/CD</li><li>服务部署</li><li>自动扩容</li><li>健康检查</li><li>滚动更新</li></ul></li></ol><br></div><br><div class="tip custom-block"><p class="custom-block-title">部署方案</p><br><p><strong>部署流程</strong></p></div><h2 id="应用设计" tabindex="-1">应用设计 <a class="header-anchor" href="#应用设计" aria-label="Permalink to &quot;应用设计&quot;">​</a></h2><p>核心目的: 基于战术设计的业务对象，转化为软件分层、接口、数据库、应用逻辑。可简述为<code>模块详细设计</code>。</p><br><h3 id="核心关注-1" tabindex="-1">核心关注 <a class="header-anchor" href="#核心关注-1" aria-label="Permalink to &quot;核心关注&quot;">​</a></h3><ul><li><code>API</code>设计: 区分查询与命令接口，明确入参、出参、请求方式。</li><li>应用服务设计: 业务流程编排(<code>接收请求-&gt;领域处理-&gt;数据入库-&gt;事件发布</code>)，不涉及业务实现细节。</li><li>数据库设计: 基于聚合对象设计数据库表，ER图；聚合内部对象持久化。</li><li>时序图设计: <code>请求&lt;--&gt;响应或异常</code>流程中的组建调用。</li><li>基建层实现: 仓储实现、消息发送实现，外部第三方调用适配器。</li><li>模块包结构: 代码目录结构分包。</li></ul><h3 id="模块分包" tabindex="-1">模块分包 <a class="header-anchor" href="#模块分包" aria-label="Permalink to &quot;模块分包&quot;">​</a></h3><br><h3 id="时序流程" tabindex="-1">时序流程 <a class="header-anchor" href="#时序流程" aria-label="Permalink to &quot;时序流程&quot;">​</a></h3><br><h3 id="库表设计" tabindex="-1">库表设计 <a class="header-anchor" href="#库表设计" aria-label="Permalink to &quot;库表设计&quot;">​</a></h3><br><h3 id="接口设计" tabindex="-1">接口设计 <a class="header-anchor" href="#接口设计" aria-label="Permalink to &quot;接口设计&quot;">​</a></h3><br><h2 id="交互设计" tabindex="-1">交互设计 <a class="header-anchor" href="#交互设计" aria-label="Permalink to &quot;交互设计&quot;">​</a></h2><h2 id="界面设计" tabindex="-1">界面设计 <a class="header-anchor" href="#界面设计" aria-label="Permalink to &quot;界面设计&quot;">​</a></h2><h2 id="编码实现" tabindex="-1">编码实现 <a class="header-anchor" href="#编码实现" aria-label="Permalink to &quot;编码实现&quot;">​</a></h2><h3 id="后端实现" tabindex="-1">后端实现 <a class="header-anchor" href="#后端实现" aria-label="Permalink to &quot;后端实现&quot;">​</a></h3><br><h3 id="前端实现" tabindex="-1">前端实现 <a class="header-anchor" href="#前端实现" aria-label="Permalink to &quot;前端实现&quot;">​</a></h3><h4 id="布局实现" tabindex="-1">布局实现 <a class="header-anchor" href="#布局实现" aria-label="Permalink to &quot;布局实现&quot;">​</a></h4><div class="warning custom-block"><p class="custom-block-title">固定布局</p><p>早期基于设备像素(<code>px</code>)作为像素单位基准，直接映射并应用。</p><p>固定布局，在小屏幕界面存在显示不全现象，在大屏幕存在大区域空白现象。</p><p>关键点: 固定大小，设备像素(<code>px</code>)。</p><br><p><strong>流式布局</strong></p><p>基于盒模型宽度百分比(<code>100%</code>)作为像素单位基准，早期用于适应电脑端屏幕。</p><p>流式布局，容器大小跟随盒模型宽度百分比缩放，但内部文本大小无法跟随盒模型宽度进行自适应。</p><p>关键点: 宽度缩放，容器流动，文本不变。</p><br><p><strong>弹性布局</strong></p><p>基于文档字体高度(<code>px</code>)作为像素单位基准，并使用其它像素单位(<code>rem、em</code>)换算处理后应用。</p><p>关键点: 文档字体高度，像素单位换算后再应用(<code>基于文档字体高度缩放全局界面</code>)。</p><br><p><strong>网格布局</strong></p><p>基于网格线绘制单元格，内部采用固定、流式、弹性等布局方式适配设备屏幕。</p><p>关键点: 网格线、单元格、支持多种布局方式。</p><br><p><strong>自适应布局</strong></p><p>基于设备分辨率，预设多套布局模板；判断并应用匹配的布局模板。</p><p>支持分辨率: 320、480、760、960、1200、1600 等。</p><p>关键点: 预设模板，判断应用，刷新重显。</p><p>应用现象: 国内网站以多级域名划分不同设备支持适配。</p><br><p>大屏适配方案</p><ul><li>像素单位: <code>rem</code>、<code>vw</code>、<code>vh</code>。</li><li>内容方式: 多采用弹性、网格。</li><li>适配策略: <code>(大变化)屏幕尺寸检测切换站点</code>或<code>(小变化)媒体查询对应样式文件</code>。</li></ul><br><p><strong>响应式布局</strong></p><p>基于页面宽度自动调整布局方式(<code>隐藏元素、调整顺序、改动布局和样式</code>)来适配所养设备宽度。</p><p>关键点: 界面宽度，布局变动(<code>隐调增删布局，变动样式</code>)、断点适配所有设备宽度屏幕(<code>一镜到底</code>)。</p><p>应用现象: 国外网站大多采用一镜到底方式断点适配所有设备宽度屏幕。</p></div><br><h4 id="组件开发" tabindex="-1">组件开发 <a class="header-anchor" href="#组件开发" aria-label="Permalink to &quot;组件开发&quot;">​</a></h4><div class="warning custom-block"><p class="custom-block-title">容器组件</p><p>容器组件使用展示组件，并通过事件交互处理业务逻辑，聚合数据状态交给展示组件渲染。</p><br><p><strong>展示组建</strong></p><p>展示组件接收并根据状态切换显示结构布局和样式内容，以此实现组件复用。</p><p>若存在交互处理，则通过事件抛出交给容器组件处理。</p><br><p><strong>拆分解耦</strong></p><ol><li>根据<code>查询、新增、修改</code>等关键词，归类为展示组件。</li><li>分析不同状态下的显示结构布局和样式内容，枚举记录状态值，用于切换显示依据。</li><li>分析不同状态下的显示结构布局和样式内容的交互能力，通过事件抛出形式交给容器组件处理。</li><li>容器组件通过事件交互处理业务逻辑，并将聚合的数据状态下发传递给展示组件。</li></ol></div><br><h4 id="逻辑实现" tabindex="-1">逻辑实现 <a class="header-anchor" href="#逻辑实现" aria-label="Permalink to &quot;逻辑实现&quot;">​</a></h4><div class="warning custom-block"><p class="custom-block-title">可视化模型</p></div><h2 id="测试验证" tabindex="-1">测试验证 <a class="header-anchor" href="#测试验证" aria-label="Permalink to &quot;测试验证&quot;">​</a></h2><h2 id="预发布验证" tabindex="-1">预发布验证 <a class="header-anchor" href="#预发布验证" aria-label="Permalink to &quot;预发布验证&quot;">​</a></h2><h2 id="上线部署" tabindex="-1">上线部署 <a class="header-anchor" href="#上线部署" aria-label="Permalink to &quot;上线部署&quot;">​</a></h2><h2 id="运维监控" tabindex="-1">运维监控 <a class="header-anchor" href="#运维监控" aria-label="Permalink to &quot;运维监控&quot;">​</a></h2>',109)])])}const h=i(e,[["render",c]]);export{n as __pageData,h as default};
